def best(t,heavy,key):
    L=[x for x in a if x['type']==t and ((x['values'][7]>0)==heavy) and x['weight']>0]
    return max(L,key=key)
for heavy in(False,True):
    tot_w=0;tot_d=0;tot_p=0;parts=[]
    for t in range(4):
        x=best(t,heavy,lambda x:sum(x['values'][:7]))
        tot_w+=x['weight'];tot_d+=sum(x['values'][:7]);tot_p+=x['values'][7];parts.append((x['name'],x['weight'],round(sum(x['values'][:7])/7,1)))
    print('heavy' if heavy else 'light',parts,'W',tot_w,'avg def',round(tot_d/7,1),'poise sum',round(tot_p,1),'maxpoise',round(tot_p*.5,1))
# median sets
for heavy in(False,True):
    tw=0;td=0;tp=0
    for t in range(4):
        L=[x for x in a if x['type']==t and ((x['values'][7]>0)==heavy) and x['weight']>0]
        tw+=S.median(x['weight'] for x in L);td+=S.median(sum(x['values'][:7])/7 for x in L);tp+=S.median(x['values'][7] for x in L)
    print('median set','heavy' if heavy else 'light','W',tw,'avgdef',round(td,1),'poise',tp)
